<?php
declare(strict_types=1);
$app=require dirname(__DIR__).'/bootstrap.php';$selector=(string)($_GET['s']??'');$token=(string)($_GET['t']??'');
if(preg_match('/\A[a-f0-9]{16}\z/',$selector)!==1||preg_match('/\A[A-Za-z0-9_-]{43}\z/',$token)!==1){http_response_code(404);exit('Linku nuk është valid.');}
$q=$app['pdo']->prepare('SELECT l.id,l.message_id,l.target_path FROM dbo.message_action_links l WHERE l.selector=:selector AND l.secret_hash=CONVERT(binary(32),:hash,2) AND (l.expires_at IS NULL OR l.expires_at>SYSUTCDATETIME())');$q->execute(['selector'=>$selector,'hash'=>hash('sha256',$token)]);$link=$q->fetch();if(!$link){http_response_code(410);exit('Linku ka skaduar.');}
$ip=hash('sha256',(string)($_SERVER['REMOTE_ADDR']??''));$ua=hash('sha256',(string)($_SERVER['HTTP_USER_AGENT']??''));$app['pdo']->beginTransaction();try{$app['pdo']->prepare('UPDATE dbo.message_action_links SET first_opened_at=COALESCE(first_opened_at,SYSUTCDATETIME()),open_count=open_count+1 WHERE id=:id')->execute(['id'=>$link['id']]);$app['pdo']->prepare("INSERT dbo.message_events(message_id,action_link_id,event_code,ip_hash,user_agent_hash) VALUES(:message,:link,'LINK_OPENED',CONVERT(binary(32),:ip,2),CONVERT(binary(32),:ua,2))")->execute(['message'=>$link['message_id'],'link'=>$link['id'],'ip'=>$ip,'ua'=>$ua]);$app['pdo']->commit();}catch(Throwable $e){if($app['pdo']->inTransaction())$app['pdo']->rollBack();throw $e;}redirect((string)$link['target_path']);
